  "鱼与熊掌不可兼得": "孟子的学生们把老师的言论整理成《孟子》一书，记录了这位儒家大师的思想。\n\n【成语含义】鱼和熊掌不能同时得到。比喻两样好东西不能都要。常用于说理议论的场合，富有思辨色彩。",
  "富贵不能淫": "孟子的学生们把老师的言论整理成《孟子》一书，记录了这位儒家大师的思想。\n\n【成语含义】富贵不能使他的思想迷惑。指意志坚定。多用于形容历史人物或与人有关的品质。",
  "威武不能屈": "孟子的学生们把老师的言论整理成《孟子》一书，记录了这位儒家大师的思想。\n\n【成语含义】武力不能使他屈服。形容人坚贞不屈。多用于形容历史人物或与人有关的品质。",
  "贫贱不能移": "孟子的学生们把老师的言论整理成《孟子》一书，记录了这位儒家大师的思想。\n\n【成语含义】贫贱不能使他改变志向。多用于形容历史人物或与人有关的品质。",
  "老吾老以及人之老": "孟子的学生们把老师的言论整理成《孟子》一书，记录了这位儒家大师的思想。\n\n【成语含义】尊敬自己的老人从而推及到尊敬别人的老人。多用于评价人的行为举止和品德修养。",
  "明察秋毫": "孟子的学生们把老师的言论整理成《孟子》一书，记录了这位儒家大师的思想。\n\n【成语含义】能看清秋天鸟兽新生的细毛。形容目光敏锐洞察细微。多用于评价人的行为举止和品德修养。",
