  "一窍不通": "这个故事记载在《吕氏春秋》中，是秦国丞相吕不韦组织门客编写的一部著作。\n\n【成语含义】没有一个窍是通的。比喻什么都不懂。多用于描写景物或借景抒情。",
  "疑似之迹": "这个故事记载在《吕氏春秋》中，是秦国丞相吕不韦组织门客编写的一部著作。\n\n【成语含义】相似的东西容易混淆。常用于说理议论的场合，富有思辨色彩。",
