  "失之东隅收之桑榆": "这个故事记载在班固的《汉书》中，记录了西汉时期的一段真实历史。\n\n【成语含义】在东方日出时失去在西方日落时收回。比喻开始有损失后来却得到好处。常用于说理议论的场合，富有思辨色彩。",
