  "疾风知劲草": "这个故事记载在班固的《汉书》中，记录了西汉时期的一段真实历史。\n\n【成语含义】猛烈大风吹过才知道哪种草最坚韧。比喻严峻考验中见人的品质。多用于形容历史人物或与人有关的品质。",
