  "乐此不疲": "这个故事记载在班固的《汉书》中，记录了西汉时期的一段真实历史。\n\n【成语含义】刘秀勤于政事乐此不疲。指对某事特别爱好而沉浸其中不觉疲倦。多用于评价人的行为举止和品德修养。",
