  "攻心为上": "这个故事发生在三国时期，记载在陈寿的《三国志》中，是三国历史的一个著名典故。\n\n【成语含义】马谡建议诸葛亮攻心为上攻城为下。指从思想上瓦解敌人。常用于战争、竞争或激烈对抗的语境。",
