  "当头棒喝": "成语\"当头棒喝\"出自史书典籍，是我国传统文化中的经典成语。\n\n【成语含义】禅宗用棒打和喝斥促人醒悟。比喻用严厉手段使人猛醒。常用于文学、艺术、学术相关的讨论。",
  "放下屠刀立地成佛": "成语\"放下屠刀立地成佛\"出自史书典籍，是我国传统文化中的经典成语。\n\n【成语含义】放下屠刀马上就能成佛。比喻恶人悔改就能成为好人。常用于说理议论的场合，富有思辨色彩。",
  "一丝不挂": "成语\"一丝不挂\"出自史书典籍，是我国传统文化中的经典成语。\n\n【成语含义】佛教指不被尘俗牵挂。后指赤身裸体。常用于文学、艺术、学术相关的讨论。",
  "冷暖自知": "成语\"冷暖自知\"出自史书典籍，是我国传统文化中的经典成语。\n\n【成语含义】水的冷暖只有喝水的人自己知道。比喻体会深浅只有自己知道。常用于说理议论的场合，富有思辨色彩。",
  "本来面目": "成语\"本来面目\"出自史书典籍，是我国传统文化中的经典成语。\n\n【成语含义】禅宗指人的本心本性。指事物原来的样子。常用于说理议论的场合，富有思辨色彩。",
  "痴人说梦": "成语\"痴人说梦\"出自史书典籍，是我国传统文化中的经典成语。\n\n【成语含义】对傻子说梦话傻子信以为真。比喻凭妄想说不能实现的话。多用于评价人的行为举止和品德修养。",
  "一尘不染": "成语\"一尘不染\"出自史书典籍，是我国传统文化中的经典成语。\n\n【成语含义】佛教指不被尘俗污染。形容品格高洁。多用于评价人的行为举止和品德修养。",
  "借花献佛": "成语\"借花献佛\"出自史书典籍，是我国传统文化中的经典成语。\n\n【成语含义】借别人的花献给佛。比喻用别人的东西做人情。多用于评价人的行为举止和品德修养。",
  "天下第一": "这个故事记载在司马迁的《史记》中，是我国历史上最著名的经典故事之一。\n\n【成语含义】天下第一。形容没有人能比得上。适用范围广泛，日常交流中常见。",
  "花言巧语": "成语\"花言巧语\"出自史书典籍，是我国传统文化中的经典成语。\n\n【成语含义】说虚假而动听的话。多用于评价人的行为举止和品德修养。",
  "名正言顺": "孔子的弟子们把老师的谆谆教诲记录下来，编成了《论语》这部经典。这句话就是孔子教导学生的话。\n\n【成语含义】名义正当道理也说得通。常用于说理议论的场合，富有思辨色彩。",
  "无中生有": "老子是道家学派的创始人，他的《道德经》虽只有五千言，却蕴含了深奥的哲学智慧。\n\n【成语含义】道家指道生万物。后指凭空捏造。多用于评价人的行为举止和品德修养。",
  "胡思乱想": "这是宋代文学家朱熹名句的由来。\n\n【成语含义】没有根据地乱想。多用于评价人的行为举止和品德修养。",
  "拐弯抹角": "成语\"拐弯抹角\"出自史书典籍，是我国传统文化中的经典成语。\n\n【成语含义】沿着弯弯曲曲的路走。比喻说话绕圈子不直截了当。多用于评价人的行为举止和品德修养。",
  "家喻户晓": "成语\"家喻户晓\"出自史书典籍，是我国传统文化中的经典成语。\n\n【成语含义】家家户户都知道。形容人人皆知。常用于文学、艺术、学术相关的讨论。",
  "两全其美": "成语\"两全其美\"出自史书典籍，是我国传统文化中的经典成语。\n\n【成语含义】做事顾全两方面使双方都满意。常用于说理议论的场合，富有思辨色彩。",
  "十全十美": "成语\"十全十美\"出自史书典籍，是我国传统文化中的经典成语。\n\n【成语含义】各方面都非常完美毫无缺陷。常用于说理议论的场合，富有思辨色彩。",
  "三番五次": "成语\"三番五次\"出自史书典籍，是我国传统文化中的经典成语。\n\n【成语含义】屡次多次。多用于评价人的行为举止和品德修养。",
  "千方百计": "这是宋代文学家朱熹名句的由来。\n\n【成语含义】想尽一切办法用尽一切计谋。多用于评价人的行为举止和品德修养。",
