  "一技之长": "成语\"一技之长\"出自史书典籍，是我国传统文化中的经典成语。\n\n【成语含义】具有某种技能或专长。适用范围广泛，日常交流中常见。",
  "一帆风顺": "这是唐代诗人孟郊名句的由来。\n\n【成语含义】船挂满帆顺风行驶。比喻非常顺利。多用于描写景物或借景抒情。",
  "一马当先": "这个故事发生在三国时期，记载在陈寿的《三国志》中，是三国历史的一个著名典故。\n\n【成语含义】作战时一马冲在最前面。比喻领先带头。常用于战争、竞争或激烈对抗的语境。",
  "双管齐下": "成语\"双管齐下\"出自史书典籍，是我国传统文化中的经典成语。\n\n【成语含义】张璪作画两手各拿一管笔同时画。比喻两件事同时进行。常用于文学、艺术、学术相关的讨论。",
  "画中有诗": "这是宋代文学家苏轼名句的由来。\n\n【成语含义】王维的画里富有诗意。形容画作意境很美。常用于文学、艺术、学术相关的讨论。",
  "诗中有画": "这是宋代文学家苏轼名句的由来。\n\n【成语含义】王维的诗意境如画。形容诗作形象生动。常用于文学、艺术、学术相关的讨论。",
  "胸无点墨": "成语\"胸无点墨\"出自史书典籍，是我国传统文化中的经典成语。\n\n【成语含义】胸中一点墨水都没有。形容没有文化。常用于文学、艺术、学术相关的讨论。",
  "妙手回春": "成语\"妙手回春\"出自史书典籍，是我国传统文化中的经典成语。\n\n【成语含义】形容医术高明能把垂危的病人治好。多用于形容历史人物或与人有关的品质。",
  "起死回生": "这个故事记载在司马迁的《史记》中，是我国历史上最著名的经典故事之一。\n\n【成语含义】把快要死的人救活。形容医术高明。多用于形容历史人物或与人有关的品质。",
  "对症下药": "这个故事发生在三国时期，记载在陈寿的《三国志》中，是三国历史的一个著名典故。\n\n【成语含义】华佗针对病症开药。比喻针对问题采取相应措施。常用于说理议论的场合，富有思辨色彩。",
  "望闻问切": "这个故事与中医经典《难经》有关。\n\n【成语含义】中医的四种诊断方法。指全面诊断。多用于形容历史人物或与人有关的品质。",
  "讳疾忌医": "成语\"讳疾忌医\"出自史书典籍，是我国传统文化中的经典成语。\n\n【成语含义】隐瞒疾病不愿医治。比喻掩饰错误不愿改正。多用于评价人的行为举止和品德修养。",
  "杏林春暖": "成语\"杏林春暖\"出自史书典籍，是我国传统文化中的经典成语。\n\n【成语含义】董奉在杏林行医不收钱。指医德高尚的医术。多用于形容历史人物或与人有关的品质。",
  "如坐针毡": "这个故事记载在房玄龄等人编撰的《晋书》中，是两晋时期的一段真实历史。\n\n【成语含义】像坐在有针的毡子上。形容心神不安。多用于描写人的内心感受和人际关系。",
  "回光返照": "成语\"回光返照\"出自史书典籍，是我国传统文化中的经典成语。\n\n【成语含义】日落时光线反射天空。比喻人临死前精神突然好转。多用于描写景物或借景抒情。",
