  "星星之火可以燎原": "《尚书》是中国最早的史书之一，记载了上古时期的历史文献。\n\n【成语含义】微小火星可以烧遍原野。常用于战争、竞争或激烈对抗的语境。",
  "雨后春笋": "成语\"雨后春笋\"出自史书典籍，是我国传统文化中的经典成语。\n\n【成语含义】春天下雨后竹笋长得很快。比喻新生事物大量出现。多用于描写景物或借景抒情。",
