  "如虎添翼": "这个故事发生在三国时期，记载在陈寿的《三国志》中，是三国历史的一个著名典故。\n\n【成语含义】好像老虎长出了翅膀。比喻强大的变得更强大。多用于比喻性的语境，形象生动。",
