  "山鸡舞镜": "成语\"山鸡舞镜\"出自史书典籍，是我国传统文化中的经典成语。\n\n【成语含义】山鸡对着镜子跳舞。比喻自我欣赏。多用于比喻性的语境，形象生动。",
