  "咬文嚼字": "成语\"咬文嚼字\"出自史书典籍，是我国传统文化中的经典成语。\n\n【成语含义】过分推敲字句。指死抠字眼不领会精神。常用于文学、艺术、学术相关的讨论。",
  "笔耕不辍": "这个故事记载在班固的《汉书》中，记录了西汉时期的一段真实历史。\n\n【成语含义】坚持写作不停止。常用于文学、艺术、学术相关的讨论。",
