  "日久生情": "这是宋代文学家欧阳修名句的由来。\n\n【成语含义】相处久了就产生感情。多用于描写人的内心感受和人际关系。",
  "一见钟情": "成语\"一见钟情\"出自史书典籍，是我国传统文化中的经典成语。\n\n【成语含义】一见面就产生了爱情。多用于描写人的内心感受和人际关系。",
