  "郑和下西洋": "这个故事记载在《明史》中，记录了明朝的历史。\n\n【成语含义】郑和七次率领船队出使西洋。指伟大的航海壮举。多用于形容历史人物或与人有关的品质。",
  "康乾盛世": "这个故事记载在《清史稿》中，来自清朝的历史记录。\n\n【成语含义】康熙乾隆时期的繁荣盛世。多用于形容历史人物或与人有关的品质。",
