  "浩浩荡荡": "这是宋代文学家范仲淹名句的由来。\n\n【成语含义】水势壮阔。形容气势壮大。多用于描写景物或借景抒情。",
  "波澜壮阔": "成语\"波澜壮阔\"出自史书典籍，是我国传统文化中的经典成语。\n\n【成语含义】波涛壮阔。形容声势雄伟。多用于描写景物或借景抒情。",
  "风起云涌": "这是宋代文学家苏轼名句的由来。\n\n【成语含义】大风刮起乌云涌来。比喻事物迅速发展声势浩大。多用于描写景物或借景抒情。",
  "举世闻名": "成语\"举世闻名\"出自史书典籍，是我国传统文化中的经典成语。\n\n【成语含义】全世界都知道。形容非常著名。多用于形容历史人物或与人有关的品质。",
  "闻名遐迩": "成语\"闻名遐迩\"出自史书典籍，是我国传统文化中的经典成语。\n\n【成语含义】远近闻名。形容名声很大。多用于形容历史人物或与人有关的品质。",
  "名扬四海": "成语\"名扬四海\"出自史书典籍，是我国传统文化中的经典成语。\n\n【成语含义】名声传遍天下。多用于形容历史人物或与人有关的品质。",
  "可歌可泣": "成语\"可歌可泣\"出自史书典籍，是我国传统文化中的经典成语。\n\n【成语含义】值得歌颂赞美使人感动流泪。多用于评价人的行为举止和品德修养。",
  "遗臭万年": "这个故事记载在《世说新语》中，记录了魏晋时期名士们的言行轶事。\n\n【成语含义】坏名声永远流传下去。多用于形容历史人物或与人有关的品质。",
  "千锤百炼": "成语\"千锤百炼\"出自史书典籍，是我国传统文化中的经典成语。\n\n【成语含义】比喻经过多次艰苦锻炼。多用于评价人的行为举止和品德修养。",
  "百炼成钢": "成语\"百炼成钢\"出自史书典籍，是我国传统文化中的经典成语。\n\n【成语含义】铁经过百次锻炼成钢。比喻久经锻炼变得坚强。多用于评价人的行为举止和品德修养。",
  "风雨无阻": "成语\"风雨无阻\"出自史书典籍，是我国传统文化中的经典成语。\n\n【成语含义】刮风下雨也阻挡不了。指不管什么困难都坚持。多用于评价人的行为举止和品德修养。",
  "雷厉风行": "这是宋代文学家苏轼名句的由来。\n\n【成语含义】像雷一样猛烈像风一样迅速。形容执行政令严厉快速。多用于评价人的行为举止和品德修养。",
  "大刀阔斧": "这个故事出自施耐庵的《水浒传》。\n\n【成语含义】像用大刀阔斧一样。比喻办事果断有魄力。多用于评价人的行为举止和品德修养。",
  "斩钉截铁": "这是宋代文学家朱熹名句的由来。\n\n【成语含义】比喻说话做事坚决果断。多用于评价人的行为举止和品德修养。",
  "当机立断": "成语\"当机立断\"出自史书典籍，是我国传统文化中的经典成语。\n\n【成语含义】抓住时机果断做出决定。多用于评价人的行为举止和品德修养。",
