  "推敲": "成语\"推敲\"出自史书典籍，是我国传统文化中的经典成语。\n\n【成语含义】贾岛斟酌用推还是敲字。比喻反复琢磨字句。常用于文学、艺术、学术相关的讨论。",
  "一字之师": "成语\"一字之师\"出自史书典籍，是我国传统文化中的经典成语。\n\n【成语含义】齐己改一字拜郑谷为师。指改正一个字的老师。常用于文学、艺术、学术相关的讨论。",
