  "不为良相便为良医": "成语\"不为良相便为良医\"出自史书典籍，是我国传统文化中的经典成语。\n\n【成语含义】范仲淹说不能当好宰相就当个好医生。指利国利民。多用于形容历史人物或与人有关的品质。",
  "先天下之忧而忧后天下之乐而乐": "这是宋代文学家范仲淹名句的由来。\n\n【成语含义】在天下人忧之前忧在天下人乐之后乐。多用于形容历史人物或与人有关的品质。",
  "醉翁之意不在酒在乎山水之间": "这是宋代文学家欧阳修名句的由来。\n\n【成语含义】醉翁之意不在酒而在山水之间。比喻表面目的之外有真意。多用于形容历史人物或与人有关的品质。",
  "环滁皆山也": "这是宋代文学家欧阳修名句的由来。\n\n【成语含义】滁州四面环山。开篇名句。多用于描写景物或借景抒情。",
  "岳阳楼记": "这是宋代文学家范仲淹名句的由来。\n\n【成语含义】范仲淹写岳阳楼的名篇。常用于文学、艺术、学术相关的讨论。",
  "前赤壁赋": "这是宋代文学家苏轼名句的由来。\n\n【成语含义】苏轼在赤壁写的名赋。常用于文学、艺术、学术相关的讨论。",
  "哀吾生之须臾羡长江之无穷": "这是宋代文学家苏轼名句的由来。\n\n【成语含义】感叹人生短暂羡慕长江水无穷无尽。多用于描写人的内心感受和人际关系。",
