  "取之无尽用之不竭": "这是宋代文学家苏轼名句的由来。\n\n【成语含义】拿不完用不尽。形容资源丰富。多用于描写景物或借景抒情。",
  "清风徐来水波不兴": "这是宋代文学家苏轼名句的由来。\n\n【成语含义】清风缓缓吹来水面没有波浪。描写平静的江景。多用于描写景物或借景抒情。",
